const int item_finish_count = 2208;

const char* weapon(const int weapon_index)
{
    if (weapon_index < 0 || weapon_index >= weapon_model_count)
        return nullptr;
    return weapon_model[weapon_index];
}

const Finish* finish(const int item_index)
{
    if (item_index < 0 || item_index >= item_finish_count)
        return nullptr;
    const auto& entry = item_finish[item_index];
    return entry.material || entry.color ? &entry : nullptr;
}

